import{_ as s,o,c as i,a7 as n}from"./chunks/framework.Cv3pX6x0.js";const u=JSON.parse('{"title":"Permissions","description":"How the Axolotl-PM permission system works, including permission names, group permissions such as pocketmine.group.operator, and how conflicting values are resolved.","frontmatter":{"title":"Permissions","outline":"deep","description":"How the Axolotl-PM permission system works, including permission names, group permissions such as pocketmine.group.operator, and how conflicting values are resolved.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/permissions"}]]},"headers":[],"relativePath":"docs/permissions.md","filePath":"docs/permissions.md","lastUpdated":1790689997000}'),r={name:"docs/permissions.md"};function a(t,e,p,l,m,c){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>Axolotl-PM includes a powerful permission system, similar in functionality to the one found in Bukkit. It allows fine-grained control of access to various parts of the server functionality, such as:</p><ul><li>Ability to use individual commands</li><li>Whether or not the user can see administrative broadcasts when a command is used (e.g. when someone uses <code>/op</code>)</li></ul><p>In addition, plugins can offer permissions to allow customising access to behaviours that they offer.</p><p>Axolotl-PM doesn’t directly offer any way to use permissions at the time of writing (August 2022), but you can find permission management plugins in the “Admin Tools” section on Poggit.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Poggit is now read-only. Existing plugins can still be found there, but no new plugins or updates are being published.</p></div><h2 id="built-in-permissions" tabindex="-1">Built-in permissions <a class="header-anchor" href="#built-in-permissions" aria-label="Permalink to &quot;Built-in permissions&quot;">​</a></h2><ul><li><a href="/website/previews/9f14c22779bf/docs/core-permissions">List of built-in permissions</a></li></ul><h2 id="names" tabindex="-1">Names <a class="header-anchor" href="#names" aria-label="Permalink to &quot;Names&quot;">​</a></h2><p>Permissions are referred to by names, which usually look something like <code>pocketmine.command.help</code>.</p><p>There’s no special requirements on permission names, but the de facto standard in community plugins is to separate the parts using <code>.</code>, and use a common prefix for permissions for similar things. For example all Axolotl-PM core commands have permissions using the prefix <code>pocketmine.command.</code>.</p><h2 id="grouping-permission-nodes-together" tabindex="-1">Grouping permission nodes together <a class="header-anchor" href="#grouping-permission-nodes-together" aria-label="Permalink to &quot;Grouping permission nodes together&quot;">​</a></h2><p>While most permissions affect one specific thing (e.g. whether or not a player is allowed to use a command), permissions may also automatically grant (or deny) other permissions when assigned. These special permissions are known as “group permissions”.</p><p>An example of a group permission is <code>pocketmine.group.operator</code>, which, when granted, grants permissions such as <code>pocketmine.command.op.give</code> which enable access to operator commands.</p><p>This is useful if you want to assign the same set of permissions to multiple users (or other groups).</p><h2 id="permission-precedence" tabindex="-1">Permission precedence <a class="header-anchor" href="#permission-precedence" aria-label="Permalink to &quot;Permission precedence&quot;">​</a></h2><p>Because of group permissions, it’s possible that a user may receive multiple conflicting values for the same permission.</p><p>Permission values are resolved in the following order:</p><ul><li>Explicitly overridden permissions take maximum priority. This means that, for example, a player can receive <code>pocketmine.group.operator</code>, but be denied <code>pocketmine.command.op.give</code>, allowing them access to all operator commands <strong>except</strong> <code>/op</code>.</li><li>If the permission is not overridden directly, the value from the most recently assigned group permission will be used.</li></ul>',19)])])}const h=s(r,[["render",a]]);export{u as __pageData,h as default};
